const words=[
['abate','To become less intense or widespread'],['aberration','A departure from what is normal or expected'],['abstain','To deliberately choose not to do something'],['acute','Sharp, severe, or highly perceptive'],['adverse','Unfavorable or harmful'],['ambiguous','Open to more than one interpretation'],['anomaly','Something that differs from what is usual'],['apathy','Lack of interest, feeling, or concern'],['arbitrary','Based on random choice rather than a clear reason'],['bolster','To support or strengthen'],['candid','Truthful and straightforward'],['censure','To express strong formal disapproval'],['coherent','Logical, consistent, and easy to follow'],['compelling','Strongly persuasive or convincing'],['concede','To admit that something is true or valid'],['concise','Brief while still communicating clearly'],['conspicuous','Easy to notice; prominent'],['contemplate','To think about something carefully'],['contradict','To state the opposite or show inconsistency'],['conventional','Following what is generally accepted'],['corroborate','To support a claim with confirming evidence'],['credible','Believable and trustworthy'],['cursory','Quick and not thorough'],['deference','Respectful regard for another’s judgment'],['diligent','Showing steady, careful effort'],['disparity','A noticeable difference or inequality'],['eclectic','Drawing ideas or styles from varied sources'],['elicit','To draw out a response or information'],['emulate','To imitate with the aim of matching or surpassing'],['empirical','Based on observation or experience'],['equitable','Fair and impartial'],['exacerbate','To make a problem or condition worse'],['explicit','Clearly stated and leaving little doubt'],['feasible','Possible and practical to do'],['fluctuate','To rise and fall irregularly'],['fortify','To strengthen or protect'],['impartial','Fair; not favoring one side'],['inherent','Existing as a natural or essential part'],['mitigate','To make something less severe'],['notion','An idea, belief, or general understanding'],['nuance','A subtle difference in meaning or expression'],['objective','Based on facts rather than personal feelings'],['obscure','Not clearly understood or not well known'],['ostensible','Appearing to be true, though not necessarily so'],['pervasive','Spread throughout and difficult to avoid'],['plausible','Seeming reasonable or likely'],['prominent','Important, noticeable, or well known'],['qualify','To limit or modify the meaning of a statement'],['reconcile','To restore agreement or make consistent'],['refute','To prove a claim or argument is wrong'],['relevant','Closely connected to the matter at hand'],['resilient','Able to recover quickly after difficulty'],['substantiate','To support with evidence or facts'],['tentative','Not final or certain; subject to change'],['undermine','To weaken gradually or secretly'],['validate','To confirm that something is sound or legitimate'],['viable','Capable of working successfully']
].map(([word,definition])=>({word,definition}));
const key='sat-word-sprint-v1';let saved=JSON.parse(localStorage.getItem(key)||'{}');if(!saved.best)saved.best=0;if(!saved.missed)saved.missed=[];let queue=[],index=0,score=0,streak=0,locked=false;
const $=id=>document.getElementById(id),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function start(){queue=[...words].sort(()=>Math.random()-.5).slice(0,10);index=0;score=0;streak=0;show()}
function show(){locked=false;const item=queue[index],wrong=words.filter(x=>x.word!==item.word).sort(()=>Math.random()-.5).slice(0,3),choices=[item,...wrong].sort(()=>Math.random()-.5);$('review').hidden=true;$('quiz').innerHTML='<div class="status"><span>SAT VOCABULARY · QUESTION '+(index+1)+' OF 10</span><span class="score">SCORE '+score+' · STREAK '+streak+'</span></div><div class="bar"><span style="width:'+((index/10)*100)+'%"></span></div><div class="question"><p class="instruction">Choose the best definition of:</p><h2>'+esc(item.word)+'</h2></div><div class="choices">'+choices.map((x,i)=>'<button class="choice" data-i="'+i+'">'+esc(x.definition)+'</button>').join('')+'</div><p class="feedback" id="feedback" role="status" aria-live="polite"></p><p class="tip">Tip · Say each word aloud and use it in a sentence after answering.</p>';document.querySelectorAll('.choice').forEach((b,i)=>b.onclick=()=>answer(b,choices[i],item))}
function answer(button,choice,item){if(locked)return;locked=true;document.querySelectorAll('.choice').forEach(b=>b.disabled=true);if(choice.word===item.word){score++;streak++;button.classList.add('correct');$('feedback').textContent='Correct — '+item.word+' means: '+item.definition+'.'}else{streak=0;button.classList.add('wrong');if(!saved.missed.includes(item.word))saved.missed.push(item.word);$('feedback').textContent='The best answer is: '+item.definition+'.';document.querySelectorAll('.choice').forEach(b=>{if(b.textContent===item.definition)b.classList.add('correct')})}saved.best=Math.max(saved.best,score);localStorage.setItem(key,JSON.stringify(saved));setTimeout(()=>{index++;if(index<10)show();else finish()},850)}
function finish(){$('quiz').innerHTML='<div class="summary"><p class="eyebrow">SPRINT COMPLETE</p><h2>Nice work.</h2><p>Your score</p><strong>'+score+' / 10</strong><p>Best score: '+saved.best+'</p><button class="primary" id="again">Start another sprint</button> <button class="primary" id="reviewBtn">Review missed words ('+saved.missed.length+')</button></div>';document.getElementById('again').onclick=start;document.getElementById('reviewBtn').onclick=renderReview}
function renderReview(){$('review').hidden=false;const missed=words.filter(w=>saved.missed.includes(w.word));$('review').innerHTML='<h2>Review missed words</h2>'+(missed.length?missed.map(w=>'<article class="review-word"><strong>'+esc(w.word)+'</strong><div>'+esc(w.definition)+'</div></article>').join(''):'<p>Nothing to review yet. Keep going!</p>')+'<button class="primary" id="clear">Clear review list</button>';document.getElementById('clear').onclick=()=>{saved.missed=[];localStorage.setItem(key,JSON.stringify(saved));renderReview()}}
start();
